// Shared, editable contact defaults supplied by the owner; public in the hosted source.
export const DEFAULT_SETTINGS={restaurant:'3247 California Ave SW, Seattle, WA 98116',mike:'+12062508612',rate:null,helpPhone:'+13602015208'};
export function applySettingsDefaults(state){let changed=false;for(const key of ['restaurant','mike','helpPhone'])if(!String(state.settings[key]||'').trim()&&DEFAULT_SETTINGS[key]){state.settings[key]=DEFAULT_SETTINGS[key];changed=true;}if(!state.settings.contactDefaultsVersion){const phone=String(state.settings.mike||'').replace(/\D/g,'').replace(/^1(?=\d{10}$)/,'');if(phone==='3602015208'){state.settings.mike=DEFAULT_SETTINGS.mike;changed=true;}state.settings.contactDefaultsVersion=1;changed=true;}if(state.settings.restaurant==='Sample restaurant, Seattle, WA'){state.settings.restaurant=DEFAULT_SETTINGS.restaurant;changed=true;}return changed;}
